import json

FLOW_PATH = "/work/output/artifacts/skill-flow-inline-agent-robust/EmailTriage/EmailTriage/EmailTriage.flow"
AGENT_PROJECT_ID = "36955009-66f8-4658-b889-5c4803023189"
MODEL = "anthropic.claude-sonnet-4-6"

# Read existing flow (for trigger definition + IDs)
flow = json.load(open(FLOW_PATH))
trigger_def = next(d for d in flow["definitions"] if d["nodeType"] == "core.trigger.manual")

# Read registry definitions
auto_def = json.load(open("/tmp/autonomous_def.json"))["Data"]["Node"]
end_def   = json.load(open("/tmp/end_def.json"))["Data"]["Node"]

# Build updated flow
flow["nodes"] = [
    {
        "id": "start",
        "type": "core.trigger.manual",
        "typeVersion": "1.0",
        "display": {"label": "Manual trigger"},
        "inputs": {
            "entryPointId": flow["nodes"][0]["inputs"]["entryPointId"],
            "isDefaultEntryPoint": True
        }
    },
    {
        "id": "emailClassifier",
        "type": "uipath.agent.autonomous",
        "typeVersion": "1.2",
        "display": {"label": "Classify Email"},
        "inputs": {
            "systemPrompt": "You are an email triage specialist.",
            "userPrompt": "Classify the following support email.",
            "model": MODEL,
            "source": AGENT_PROJECT_ID,
            "agentInputVariables": [
                {
                    "id": "start__output__emailSubject",
                    "type": "string",
                    "binding": "=$vars.start.output.emailSubject",
                    "description": "Email subject line"
                },
                {
                    "id": "start__output__emailBody",
                    "type": "string",
                    "binding": "=$vars.start.output.emailBody",
                    "description": "Email body text"
                },
                {
                    "id": "start__output__emailFrom",
                    "type": "string",
                    "binding": "=$vars.start.output.emailFrom",
